import { FormSection, ProfileHeader, StickyActionBar, type Profile } from '@gntik-ai/blocks';
import { Field, FieldDescription, FieldLabel, Input, SimpleSelect, Stack } from '@gntik-ai/ui';
import { useState } from 'react';
import { locales as defaultLocales, profile as defaultProfile, profileValues, timeZones as defaultTimeZones, type ProfileFormValues, type SelectOption } from './data';
import { SettingsFrame, type SettingsFrameOptions } from './SettingsFrame';

export interface SettingsProfileProps extends SettingsFrameOptions {
  profile: Profile;
  /** Saved form values. */
  values: ProfileFormValues;
  locales: SelectOption[];
  timeZones: SelectOption[];
  /** Persists the form. A returned promise shows the saving state. */
  onSave: (values: ProfileFormValues) => void | Promise<void>;
  onAvatarChange: (file: File) => void;
}

/** Profile settings: ProfileHeader, personal and regional FormSections, StickyActionBar. */
export default function SettingsProfilePage({
  profile = defaultProfile,
  values: saved = profileValues,
  locales = defaultLocales,
  timeZones = defaultTimeZones,
  onSave,
  onAvatarChange,
  ...frame
}: Partial<SettingsProfileProps>) {
  const [base, setBase] = useState(saved);
  const [draft, setDraft] = useState(saved);
  const [saving, setSaving] = useState(false);
  const dirty = (Object.keys(draft) as Array<keyof ProfileFormValues>).some((k) => draft[k] !== base[k]);
  const set = (key: keyof ProfileFormValues) => (value: string | null) => setDraft((d) => ({ ...d, [key]: value ?? '' }));

  const save = async () => {
    setSaving(true);
    try {
      await onSave?.(draft);
      setBase(draft);
    } finally {
      setSaving(false);
    }
  };

  return (
    <SettingsFrame page="profile" description="How other members see you across the workspace." {...frame}>
      <ProfileHeader profile={{ ...profile, name: base.name }} headingLevel="h2" onEdit={null} onAvatarChange={onAvatarChange} />
      <Stack gap={8}>
        <FormSection title="Personal details" description="Your name and email are visible to everyone in the workspace." divided>
          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
            <Field>
              <FieldLabel>Full name</FieldLabel>
              <Input value={draft.name} onValueChange={set('name')} autoComplete="name" />
            </Field>
            <Field>
              <FieldLabel>Email</FieldLabel>
              <Input type="email" value={draft.email} onValueChange={set('email')} autoComplete="email" />
              <FieldDescription>We send a confirmation link when it changes.</FieldDescription>
            </Field>
          </div>
        </FormSection>
        <FormSection title="Language and region" description="Used for dates, numbers and email digests." divided>
          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
            <SimpleSelect label="Locale" items={locales} value={draft.locale} onValueChange={set('locale')} className="w-full" />
            <SimpleSelect label="Time zone" items={timeZones} value={draft.timeZone} onValueChange={set('timeZone')} className="w-full" />
          </div>
        </FormSection>
      </Stack>
      <StickyActionBar dirty={dirty} saving={saving} onSave={() => void save()} onCancel={() => setDraft(base)} aria-label="Profile changes" />
    </SettingsFrame>
  );
}

import { PageHeader, type PageChromeAction } from '@gntik-ai/blocks';
import { SettingsLayout, type SettingsLayoutProps } from '@gntik-ai/ui';
import type { ReactNode } from 'react';
import { ConsoleShell, type ConsoleShellProps } from '../shared/ConsoleShell';
import { settingsBreadcrumbs, settingsNav, settingsTitle, type SettingsNavExtraItem, type SettingsPageId } from './settings-nav';

/** Props every settings template accepts for the frame around its content. */
export interface SettingsFrameOptions {
  /** Route base for the section nav (e.g. "/settings" → links). Without it the items are buttons. */
  basePath?: string;
  /**
   * Called when another settings section is chosen (a built-in page id, or the id of one of
   * `extraNavItems`).
   */
  // Method syntax keeps `(page: SettingsPageId) => void` handlers assignable.
  onNavigate?(page: SettingsPageId | (string & {})): void;
  /** The product's own settings pages, added to the section nav (see `settingsNav`). */
  extraNavItems?: readonly SettingsNavExtraItem[];
  /** ConsoleShell props (app nav, user, workspaces, topbar). */
  shell?: Omit<ConsoleShellProps, 'children'>;
}

export interface SettingsFrameProps extends SettingsFrameOptions {
  /** Current page: a built-in id or the id of an extra nav item. */
  page: SettingsPageId | (string & {});
  /** Header title; defaults to the built-in page title or the extra item's label. */
  title?: ReactNode;
  description?: ReactNode;
  /** Header actions (PageHeader). */
  actions?: PageChromeAction[];
  width?: SettingsLayoutProps['width'];
  children: ReactNode;
}

/**
 * Glue shared by the settings templates: ConsoleShell with SettingsLayout in its main area,
 * the nine-page section nav plus any `extraNavItems` (current page selected) and a PageHeader as the layout header.
 * SettingsLayout is `embedded`: ConsoleShell already owns <main> and the skip link.
 */
export function SettingsFrame({ page, title, description, actions = [], width, basePath, onNavigate, extraNavItems, shell, children }: SettingsFrameProps) {
  const label = extraNavItems?.find((i) => i.id === page)?.label ?? settingsTitle(page);
  return (
    <ConsoleShell currentHref="/settings" breadcrumbs={settingsBreadcrumbs(page, label)} {...shell}>
      <SettingsLayout
        embedded
        groups={settingsNav(basePath, extraNavItems)}
        value={page}
        onValueChange={(key) => onNavigate?.(key)}
        mainId="settings-content"
        width={width}
        header={<PageHeader breadcrumbs={null} title={title ?? label} description={description} status="" meta={[]} tabs={null} actions={actions} />}
      >
        {children}
      </SettingsLayout>
    </ConsoleShell>
  );
}

